script:
frappe.ui.form.on('Location', {
  setup(frm) {
    frm.set_query('location_subtype', function() {
      if (!frm.doc.location_type) {
        return { filters: {} };
      }
      return {
        filters: { location_type: frm.doc.location_type }
      };
    });
  },
  refresh(frm) {
    // Show/hide location_subtype field based on has_subtype
    frappe.call({
      method: 'frappe.client.get_value',
      args: {
        doctype: 'Location Type',
        filters: { name: frm.doc.location_type },
        fieldname: ['has_subtype']
      },
      callback: function(r) {
        if (r.message) {
          const has_subtype = r.message.has_subtype;
          frm.set_df_property('location_subtype', 'hidden', !has_subtype);
        }
      }
    });
  },
  location_type(frm) {
    // Clear subtype if the type changes
    frm.set_value('location_subtype', null);
    // Show/hide field based on has_subtype
    if (frm.doc.location_type) {
      frappe.call({
        method: 'frappe.client.get_value',
        args: {
          doctype: 'Location Type',
          filters: { name: frm.doc.location_type },
          fieldname: ['has_subtype']
        },
        callback: function(r) {
          if (r.message) {
            const has_subtype = r.message.has_subtype;
            frm.set_df_property('location_subtype', 'hidden', !has_subtype);
          }
        }
      });
    } else {
      frm.set_df_property('location_subtype', 'hidden', true);
    }
  }
});
